            lib.rank.rarity.epic.addArray(['猎杀者', '暗夜之歌', '异形', '防爆特警', '阿拉贡', '夜魔', '德古拉', '尼奥', '邪念', '艾斯德斯', '桐生一马', '龙裔', '塞尔达', '不动明']);
            lib.rank.rarity.legend.addArray(['北溟巨鲲', '宇文拓', '晓美焰', '祸灵梦', '维吉尔', '真魔人', '恶灵骑士', '地狱少女', '死亡骑士', '武庚', '林克', '杰诺斯', '天启坦克', '机械哥斯拉', '危险流浪者', '魑魅魍魉', '刑天', '黑白无常', '金翅鹏', '牛头马面', '远古巨龙', '幽冥大帝', '应龙', '炼狱龙', '凶恶年兽', '煌黑龙', '利维坦', '僵尸龙', '路西法', '合体年兽', '亡灵龙', '高达一号', '终结者', '克苏鲁', '九天玄女', '死亡女神', '收割者', '飞升吸血鬼', '奎托斯', '天命人', '机械吕布', '歼灭者', '帝王蟹', '毁灭战士', '加农道夫', '雷电', '电锯人', '哨兵坦克', '基洛夫空艇', '炮艇机', '将军刽子手', '追踪者', '澹台烬', '战斗暴龙兽', '库巴', '炽天使', '芬利尔']);
