                        血咒: {
                            audio: 'ext:神域/audio:1',
                            trigger: {
                                player: 'phaseBegin',
                            },
                            intro: {
                                content(storage, player) {
                                    var name = get.translation(player);
                                    if (storage == 1) {
                                        return '每当一名角色(' + name + '除外)受到一次伤害,该角色失去1点体力,' + name + '回复1点体力';
                                    } else if (storage == 2) {
                                        return '每当一名角色(' + name + '除外)造成一次伤害,该角色失去1点体力,' + name + '(若不是受伤害角色)回复1点体力';
                                    } else {
                                        return '未发动';
                                    }
                                },
                            },
                            content() {
                                'step 0';
                                var next = player.chooseControl('选项一', '选项二', 'cancel2', function () {
                                    if (Math.random() < 0.65) return 0;
                                    return 1;
                                });
                                next.prompt = get.prompt('xuezhou');
                                next.choiceList = ['每当一名其他角色在一个回合中首次受到伤害,该角色失去1点体力,你回复1点体力', '每当一名其他角色在一个回合中首次造成伤害,该角色失去1点体力,你(若不是受伤害角色)回复1点体力'];
                                ('step 1');
                                if (result.control == 'cancel2') {
                                    player.unmarkSkill('xuezhou');
                                    delete _status.xuezhou;
                                } else {
                                    player.storage.xuezhou = result.index + 1;
                                    player.markSkill('xuezhou');
                                    _status.xuezhou = player;
                                }
                            },
                            ai: {
                                threaten: 2.5,
                            },
                            global: 'xuezhou_hp',
                        },
                        幻术: {
                            enable: 'phaseUse',
                            usable: 1,
                            audio: 'ext:神域/audio:2',
                            filter(event, player) {
                                var hs = player.getCards('h');
                                if (!hs.length) return false;
                                for (var i = 0; i < hs.length; i++) {
                                    var mod2 = game.checkMod(hs[i], player, 'unchanged', 'cardEnabled2', player);
                                    if (mod2 === false) return false;
                                }
                                return true;
                            },
                            chooseButton: {
                                dialog(player) {
                                    var list = [];
                                    for (var i = 0; i < lib.inpile.length; i++) {
                                        if (get.type(lib.inpile[i]) == 'trick') list.push(['锦囊', '', lib.inpile[i]]);
                                    }
                                    return ui.create.dialog(get.translation('幻术'), [list, 'vcard']);
                                },
                                filter(button, player) {
                                    return lib.filter.filterCard({ name: button.link[2] }, player, _status.event.parent);
                                },
                                check(button) {
                                    var player = _status.event.player;
                                    var recover = 0,
                                        lose = 1,
                                        players = game.filterPlayer();
                                    for (var i of players) {
                                        if (i.hp == 1 && get.damageEffect(i, player, player) > 0 && !i.hasSha()) {
                                            return button.link[2] == 'juedou' ? 2 : -1;
                                        }
                                        if (!i.isOut()) {
                                            if (i.hp < i.maxHp) {
                                                if (get.attitude(player, i) > 0) {
                                                    if (i.hp < 2) {
                                                        lose--;
                                                        recover += 0.5;
                                                    }
                                                    lose--;
                                                    recover++;
                                                } else if (get.attitude(player, i) < 0) {
                                                    if (i.hp < 2) {
                                                        lose++;
                                                        recover -= 0.5;
                                                    }
                                                    lose++;
                                                    recover--;
                                                }
                                            } else {
                                                if (get.attitude(player, i) > 0) {
                                                    lose--;
                                                } else if (get.attitude(player, i) < 0) {
                                                    lose++;
                                                }
                                            }
                                        }
                                    }
                                    if (lose > recover && lose > 0) return button.link[2] == 'nanman' ? 1 : -1;
                                    if (lose < recover && recover > 0) return button.link[2] == 'taoyuan' ? 1 : -1;
                                    return button.link[2] == 'wuzhong' ? 1 : -1;
                                },
                                backup(links, player) {
                                    return {
                                        filterCard: true,
                                        selectCard: -1,
                                        position: 'h',
                                        audio: 'ext:神域/audio:1',
                                        popname: true,
                                        viewAs: { name: links[0][2] },
                                    };
                                },
                                prompt(links, player) {
                                    return '将全部手牌当作' + get.translation(links[0][2]) + '使用';
                                },
                            },
                            ai: {
                                order: 1,
                                result: {
                                    player(player) {
                                        var num = 0;
                                        var cards = player.getCards('h');
                                        if (cards.length >= 3 && player.hp >= 3) return 0;
                                        if (Array.isArray(cards))
                                            for (var i of cards) {
                                                num += Math.max(0, get.value(i, player, 'raw'));
                                            }
                                        num /= cards.length;
                                        num *= Math.min(cards.length, player.hp);
                                        return 12 - num;
                                    },
                                },
                                threaten: 1.6,
                            },
                        },
